using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using UnityEditor;using UnityEngine;using MashBoxSDK.AnimationStudio;using Object=UnityEngine.Object;
public static class StudioFaceOverlayValidation {
 const BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public;static StudioModelEditor editor;static StudioModelDocument doc;static MashBoxStudioViewport view;static int checks;
 static void Check(bool p,string m){if(!p)throw new Exception(m);checks++;}
 static void Call(string n,params object[] a)=>typeof(StudioModelEditor).GetMethod(n,F).Invoke(editor,a);
 static void Field(string n,object v)=>typeof(StudioModelEditor).GetField(n,F).SetValue(editor,v);
 public static void Run(){EditorApplication.delayCall+=Start;}
 static void Start(){try{StudioSettings.Current.hideObjectWireframe=false;doc=ScriptableObject.CreateInstance<StudioModelDocument>();var m=new Mesh();m.vertices=new[]{new Vector3(-1,-1,0),new Vector3(0,-1,0),new Vector3(1,-1,0),new Vector3(-1,1,0),new Vector3(0,1,0),new Vector3(1,1,0)};m.triangles=new[]{0,3,4,0,4,1,1,4,5,1,5,2};m.RecalculateNormals();doc.nodes.Add(new StudioModelDocument.Node{name="Quads",mesh=m,cutTriangles=m.triangles,cutPolygons=new int[]{0,4,0,3,4,1,0,4,1,4,5,2}});editor=new StudioModelEditor(()=>{});editor.Load(doc);editor.SelectObject(0);editor.SetToolbarComponentMode(StudioModelEditor.ComponentMode.Face);editor.Components.Add(0);Field("hoveredComponent",1);view=ScriptableObject.CreateInstance<MashBoxStudioViewport>();view.Bind(editor.Scene);view.position=new Rect(100,100,600,500);view.Show();view.LookAtDirect(Vector3.zero,Quaternion.identity,2);SceneView.duringSceneGui+=Draw;view.Repaint();}catch(Exception e){Finish(e.ToString());}}
 static Color[] Render(int kind,string name){var rt=new RenderTexture(512,512,24,RenderTextureFormat.ARGB32,RenderTextureReadWrite.Linear);rt.Create();var old=RenderTexture.active;var target=view.camera.targetTexture;var rect=view.camera.pixelRect;var t=new Texture2D(512,512,TextureFormat.RGBA32,false,true);GL.PushMatrix();try{view.camera.targetTexture=rt;view.camera.pixelRect=new Rect(0,0,512,512);Handles.SetCamera(new Rect(0,0,512,512),view.camera);RenderTexture.active=rt;GL.Viewport(new Rect(0,0,512,512));GL.Clear(true,true,Color.black);GL.LoadProjectionMatrix(view.camera.projectionMatrix);GL.modelview=view.camera.worldToCameraMatrix;
 if(kind==0)Call("DrawComponents",view);else if(kind==1)Call("DrawComponentBatches",view);else {Call("DrawSceneWireframes",view.camera);Call("DrawComponentBatches",view);Call("DrawHoveredFaceBorder",1,2.5f);}t.ReadPixels(new Rect(0,0,512,512),0,0);t.Apply();File.WriteAllBytes(Path.GetFullPath(Path.Combine(Application.dataPath,"../../face-overlay-"+name+".png")),t.EncodeToPNG());return t.GetPixels();}finally{view.camera.targetTexture=target;view.camera.pixelRect=rect;Handles.SetCamera(view.camera);GL.PopMatrix();RenderTexture.active=old;Object.DestroyImmediate(t);Object.DestroyImmediate(rt);}}
 static void Draw(SceneView s){if(s!=view||Event.current.type!=EventType.Repaint)return;SceneView.duringSceneGui-=Draw;string result;try{var fill=Render(1,"fills");var actual=Render(0,"wire-over-faces");int uploads=editor.WireBatchUploads;var repeat=Render(0,"repeat");Check(actual.SequenceEqual(repeat),"Repeated render changed");Check(editor.WireBatchUploads==uploads,"Repeated draw rebuilt wire geometry");var wrong=Render(2,"old-order");Check(actual.Where((p,i)=>Vector3.Distance(new Vector3(p.r,p.g,p.b),new Vector3(wrong[i].r,wrong[i].g,wrong[i].b))>.03f).Count()>50,"Wire ordering does not affect rendered edges");Check(fill.Count(p=>Mathf.Abs(p.r-.28f)<.02f&&Mathf.Abs(p.g-.1335f)<.02f&&Mathf.Abs(p.b-.0076f)<.02f)>100,"Amber fill opacity differs from retopology");Check(fill.Count(p=>Mathf.Abs(p.r-.1053f)<.02f&&Mathf.Abs(p.g-.4f)<.02f&&Mathf.Abs(p.b-.356f)<.02f)>100,"Cyan hover opacity differs from retopology");Field("displayXray",true);Check(Render(1,"xray-fills").SequenceEqual(fill),"Xray changed fill opacity");Field("displayXray",false);Field("hoveredComponent",0);Render(0,"selected-hover");Check((int)typeof(StudioModelEditor).GetField("drawnHover",F).GetValue(editor)==0,"Selected face cannot hover");result="PASS "+checks+" native rendered face palette, opacity, layering and cache checks";}catch(Exception e){result=e.ToString();}Finish(result);}
 static void Finish(string result){SceneView.duringSceneGui-=Draw;File.WriteAllText(Path.GetFullPath(Path.Combine(Application.dataPath,"../../face-overlay-result.txt")),result);EditorApplication.delayCall+=()=>{if(view)view.Close();editor?.Dispose();EditorApplication.Exit(result.StartsWith("PASS")?0:1);};}
}


